// The city's texts (city.js) in Portuguese, as the sentences take them: server after "O servidor" with its
// preposition ("O servidor da cidade de Brno não responde"), dataName as the subject ("O mapa técnico de Brno não
// responde de momento"), dataShort after "segundo os dados" ("segundo os dados da cidade de Brno e do OSM"), techMap
// as the object of "A carregar …" (lowercase, with its article). All the maps are masculine ("o mapa", "o cadastro").
const own = (name, of, map, data, parking, credit) => ({
  server: of, dataName: `O ${map}`, dataShort: `${data} e do OSM`, techMap: `o ${map}`,
  parkingSource: parking, rulesHead: `Larguras segundo o Manual do IPR de Praga (C.2), para ${name} a título indicativo:`, credit,
});
